internal object DuaPlDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("Słyszenie koguta lub osła", "O Allahu, proszę Cię o Twoją łaskę (kogut). — Szukam schronienia u Allaha przed Szaytanem, przeklętym (osiołkiem).", "Słysząc, jak kogut prosi o łaskę Allaha; słysząc ryczenie osła, szukaj schronienia przed Szaytanem.", "Kogut widzi anioła, a osioł diabła."),
        "dua_something_liked" to DuaText("Zobaczyć coś godnego podziwu (przed złym okiem)", "Co Allah chciał. O Allahu, pobłogosław to.", "Widząc, że coś godnego podziwu należy do kogoś, módl się o błogosławieństwo.", "Modlitwa o błogosławieństwo zapobiega złemu oku."),
        "dua_sell_buy_debt_repaid" to DuaText("Podczas spłaty długu", "Niech Allah błogosławi cię w twojej rodzinie i twoim majątku.", "Dla pożyczkodawcy przy spłacie zadłużenia.", "Zwrotem za pożyczkę jest podziękowanie i spłata."),
        "dua_talbiyah" to DuaText("Talbiyah", "Oto jestem, o Allahu, oto jestem. Oto jestem, nie masz partnera, oto jestem. Zaprawdę, wszelka chwała, błogosławieństwa i władza są Twoje. Nie masz partnera.", "Głośno po wejściu do ihram.", "Godło Hadżdż i Umrah."),
        "dua_yamani_hajar" to DuaText("Pomiędzy Rukn Yamani i Hajar Aswad", "Panie nasz, obdarz nas dobrem na tym świecie i dobrem w życiu ostatecznym i chroń nas od kary ognia.", "W tawafie, pomiędzy Zakątkiem Jemenu a Czarnym Kamieniem.", "Prorok ﷺ wyrecytował to w tym miejscu w Tawaf."),
        "dua_safa_marwa" to DuaText("Na Safie i Marwah", "Nikt nie jest godny czci poza Allahem, Jedynym, który nie ma żadnego współtowarzysza. Do Niego należy panowanie i do Niego należy chwała. On jest nad każdą rzeczą wszechwładny. Nikt nie ma prawa być czczony, z wyjątkiem samego Allaha; Spełnił swoją obietnicę, pomógł swemu słudze i sam pokonał koalicję wrogów.", "Wspinaczka na Safa i stawienie czoła Qiblah (trzy razy).", "Dhikr Proroka ﷺ na Safa i Marwah."),
        "dua_arafah" to DuaText("Najlepsza Dua Dnia Arafaha", "Nikt nie jest godny czci poza Allahem, Jedynym, który nie ma żadnego współtowarzysza. Do Niego należy panowanie i do Niego należy chwała. On jest nad każdą rzeczą wszechwładny.", "Dzień Arafaha — najlepszy duet.", "Najlepszym dua jest dua Dnia Arafaha, a najlepsze słowa to te."),
        "dua_takbeer_tashreeq" to DuaText("Takbeer-e-Tashreeq", "Allah jest Największy, Allah jest Największy. Nie ma boga prócz Allaha. Allah jest Największy, Allah jest Największy i wszelka chwała jest dla Allaha.", "Po każdej obowiązkowej modlitwie od Fajr w dniu 9 Dhul-Hijjah do Asr w dniu 13 Dhul-Hijjah.", "Przekazane przez Alego i Ibn Mas'uda (RA) — wajib według Hanafich."),
        "dua_zamzam" to DuaText("Piję Zamzam", "O Allahu, proszę Cię o pożyteczną wiedzę, obfite zaopatrzenie i lekarstwo na każdą chorobę.", "Pijąc Zamzam, rób dua na cokolwiek masz zamiar.", "Zamzam służy do tego, do czego się go pije (Ibn Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Refleksja nad stworzeniem", "Panie nasz, nie stworzyłeś tego wszystkiego na próżno. Chwała Tobie, chroń nas przed karą Ognia.", "Duet tych, którzy zastanawiają się nad stworzeniem niebios i ziemi.", "Duet ludzi zrozumienia (ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Usłyszeliśmy wezwanie do wiary", "Panie nasz, usłyszeliśmy wołanie nawoływającego do wiary, mówiącego: „Uwierz w swego Pana” i uwierzyliśmy. Panie nasz, przebacz nam nasze grzechy, oddal od nas nasze występki i spraw, abyśmy pomarli wraz ze sprawiedliwymi.", "Duet o wiarę i umieranie wśród sprawiedliwych.", "Duet o przebaczenie i dobre zakończenie."),
        "dua_q_atina_ma_waadtana" to DuaText("Daj nam to, co obiecałeś", "Panie nasz, udziel nam tego, co obiecałeś nam przez Twoich posłańców i nie zawstydzaj nas w Dniu Zmartwychwstania. Zaprawdę, nie łamiesz Swojej obietnicy.", "Schronijcie się przed hańbą w Dniu Zmartwychwstania.", "Szukając zaszczytów w życiu ostatecznym."),
        "dua_q_israfana" to DuaText("Wybacz nasze ekscesy", "Panie nasz, przebacz nam nasze grzechy i nadużycia w naszych sprawach, utwierdź nasze stopy i pomóż nam w walce z niewiernym ludem.", "Dua towarzyszy wcześniejszych proroków.", "Duet wytrwałości i przebaczenia."),
        "dua_q_jamiun_nas" to DuaText("Zbierzesz ludzkość", "Panie nasz, z pewnością zgromadzisz ludzkość w Dniu, co do którego nie ma wątpliwości. Zaprawdę, Allah nie łamie Swojej obietnicy.", "Utwierdzając pewność w Dniu Zmartwychwstania.", "Duet mocno osadzonych w wiedzy."),
        "dua_q_maash_shahidin" to DuaText("Napisz nas do Świadków", "Panie nasz, uwierzyliśmy, więc zapisz nas wśród świadków.", "Duet tych, którzy poznali prawdę i uwierzyli.", "Dua o przyjęcie własnej wiary."),
        "dua_q_la_tajalna_zalimin" to DuaText("Nie z niesprawiedliwymi", "Panie nasz, nie umieszczaj nas wśród ludzi niesprawiedliwych.", "Dua ludu al-A'raf.", "Uciekaj przed losem złoczyńców."),
        "dua_q_tawaffana_muslimin" to DuaText("Cierpliwość i śmierć jako muzułmanie", "Panie nasz, wylej na nas cierpliwość i spraw, abyśmy pomarli jako muzułmanie.", "Duet magów faraona, kiedy wierzyli.", "Cierpliwość w próbie i zakończenie na wierze."),
        "dua_q_la_tajalna_fitnah" to DuaText("To nie jest proces dla ciemiężycieli", "Na Allahu polegamy. Panie nasz, nie wystawiaj nas na próbę dla ludzi niesprawiedliwych i wybaw nas swoim miłosierdziem od ludzi niewiernych.", "Dua ludu Musa (AS).", "Duet ratunku przed uciskiem i prześladowcami."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Dua of Nuh (AS) o przebaczenie", "Panie mój, szukam schronienia u Ciebie, abym nie prosił Cię o to, o czym nie mam wiedzy. I jeśli mi nie przebaczysz i nie zmiłujesz się nade mną, będę wśród stratnych.", "Dua pokuty Proroka Nuha (AS).", "Lekcja proszenia i właściwych manier."),
        "dua_q_mudkhala_sidq" to DuaText("Wejście i wyjście prawdy", "Panie mój, spraw, abym wchodził z prawdą i wychodził z prawdą, i daj mi od siebie władzę wspierającą.", "Przed wejściem do nowego zadania, domu lub miejsca.", "Dua nauczał Proroka ﷺ w czasach Hidżry."),
        "dua_q_la_tadharni_fardan" to DuaText("Dua z Zakariya (AS) — Nie zostawiaj mnie w spokoju", "Panie mój, nie zostawiaj mnie samego, a Ty jesteś najlepszym z dziedziców.", "Dla osób poszukujących dzieci.", "Przez ten duet Allah obdarzył Yahya (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Błogosławione miejsce lądowania", "Panie mój, pozwól mi wylądować w błogosławionym miejscu lądowania, a Ty jesteś najlepszym z tych, którzy sprowadzają na ląd.", "Podczas przeprowadzki do nowego domu lub zatrzymania się gdzieś — duet Nuh (AS).", "Duet o błogosławieństwo w nowym miejscu."),
        "dua_q_amanna_faghfir" to DuaText("Wierzymy, więc przebacz nam", "Panie nasz, uwierzyliśmy, więc przebacz nam i zmiłuj się nad nami, a Ty jesteś najlepszy z miłosiernych.", "Dua prawych sług Allaha.", "Kompleksowy duet przebaczenia i miłosierdzia."),
        "dua_q_isrif_jahannam" to DuaText("Odwróć karę piekła", "Panie nasz, odwróć od nas karę piekła; zaprawdę, jego kara jest zawsze aktualna. Rzeczywiście jest to zła osada i miejsce zamieszkania.", "Duet sług Najmiłosierniejszego („Ibad ar-Rahman”).", "Koraniczny duet zapewniający schronienie przed piekłem."),
        "dua_q_hab_li_hukman" to DuaText("Dua Ibrahima (AS) — Mądrość i Jannah", "Panie mój, udziel mi mądrości i przyłącz mnie do sprawiedliwych, obdarz mnie zaszczytnym wyróżnieniem wśród późniejszych pokoleń i uczyń mnie wśród dziedziców Ogrodu Szczęśliwości.", "Prośba o mądrość, towarzystwo sprawiedliwych i raj.", "Obszerny duet Ibrahima (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Dua of Lut (AS) — Uratuj moją rodzinę", "Mój Panie, uchroń mnie i moją rodzinę od (konsekwencji) tego, co robią.", "Ochrona rodziny przed środowiskiem zła.", "Ochrona rodziny przed złem."),
        "dua_q_sulaiman_awzini" to DuaText("Dua Sulaimana (AS) za wdzięczność", "Panie mój, pozwól mi być wdzięcznym za Twoją łaskę, którą obdarzyłeś mnie i moich rodziców, i czynić dobre uczynki, które podobają się Tobie, i przyjąć mnie przez Twoje miłosierdzie pomiędzy Twoje sprawiedliwe sługi.", "Za umiejętność wdzięczności za błogosławieństwa.", "Dua wdzięczności Sulaymana (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Dua of Musa (AS) — Zraniłem się", "Mój Panie, skrzywdziłem siebie, więc przebacz mi.", "Natychmiastowa skrucha po błędzie.", "Allah przebaczył Musie (AS)."),
        "dua_q_musa_najjini" to DuaText("Dua of Musa (AS) — Ratuj mnie przed prześladowcami", "Panie mój, wybaw mnie od ludzi niesprawiedliwych.", "Kiedy boimy się prześladowców.", "Duma Musy (AS) podczas opuszczania Egiptu."),
        "dua_q_lut_unsurni" to DuaText("Dua of Lut (AS) — Pomoc przeciwko korupcjom", "Panie mój, pomóż mi w walce ze zepsutym ludem.", "O pomoc przeciwko tym, którzy szerzą korupcję.", "Duet tych, którzy mocno trzymają się prawdy."),
        "dua_q_hab_li_salihin" to DuaText("Dua Ibrahima (AS) dla Sprawiedliwego Dziecka", "Panie mój, daj mi (dziecko) spośród sprawiedliwych.", "Prośba o prawe dzieci.", "Dzięki temu dua Isma'il (AS) został przyznany."),
        "dua_q_wasita_kulla_shay" to DuaText("Dua Aniołów Niosących Tron", "Panie nasz, Ty obejmujesz wszystko miłosierdziem i wiedzą, więc przebacz tym, którzy pokutują i idą Twoją drogą, i chroń ich przed karą piekielną.", "Aniołowie noszący tron ​​tworzą ten duet dla wierzących.", "Recytowane z intencją włączenia do duetu aniołów."),
        "dua_q_ikhwanina" to DuaText("Za naszych braci, którzy nas poprzedzili", "Panie nasz, przebacz nam i naszym braciom, którzy nas poprzedzili w wierze, i nie wkładaj w nasze serca urazy wobec wierzących. Panie nasz, Ty naprawdę jesteś Dobry i Miłosierny.", "Dua dla wierzących, którzy przyszli wcześniej i o czyste serce.", "Duet dla szlachetnych Towarzyszy (RA) i wcześniejszych wyznawców."),
        "dua_q_alayka_tawakkalna" to DuaText("Na Tobie polegamy (Ibrahim AS)", "Panie nasz, na Tobie polegamy, do Ciebie się zwracamy i do Ciebie jest powrót. Panie nasz, nie wystawiaj nas na próbę dla niewiernych i przebacz nam. Panie nasz, Ty naprawdę jesteś Wszechmogący, Mądry.", "Dua Ibrahima (AS) i jego towarzyszy.", "Duet polegania na Allahu i zwracania się do Niego."),
        "dua_q_atmim_nurana" to DuaText("Udoskonalaj nasze światło", "Panie nasz, udoskonal dla nas nasze światło i przebacz nam. Zaprawdę, Ty masz władzę nad każdą rzeczą.", "Duet wierzących w Dniu Zmartwychwstania.", "Prośba o światło na Sirat."),
        "dua_q_asiya_baytan" to DuaText("Dua z Azji — Dom w Jannah", "Panie mój, zbuduj mi przy Tobie dom w Raju, wybaw mnie od faraona i jego czynów i wybaw mnie od ludu niesprawiedliwego.", "Dua Asiji, żony faraona.", "Allah uczynił ją przykładem dla wierzących."),
        "dua_adhan_response" to DuaText("Odpowiedź na Adhan", "Nie ma mocy ani mocy, jak tylko u Allaha.", "Powtórz, co mówi muezin; w „Hayya „alas-salah” i „Hayya „alal-falah” mówią to.", "Ktokolwiek odpowie sercem, wejdzie do Raju."),
        "dua_adhan_shahadah" to DuaText("Po Szahadzie Muazzina", "I ja również świadczę, że nikt nie jest godny czci poza Allahem, Jedynym, który nie ma żadnego współtowarzysza, i że Muhammad ﷺ jest Jego sługą i Wysłannikiem. Jestem zadowolony z Allaha jako Pana, z Muhammada ﷺ jako Wysłannika i islamu jako religii.", "Po wysłuchaniu świadectwa wiary muezzina.", "Jego grzechy zostały odpuszczone."),
        "dua_istiftah_baid" to DuaText("Otwierający Dua: Oddal mnie od grzechów", "O Allahu, oddal mnie od moich grzechów, tak jak oddaliłeś wschód od zachodu. O Allahu, oczyść mnie z grzechów, tak jak biała szata oczyszcza się z brudu. O Allahu, zmyj moje grzechy wodą, śniegiem i gradem.", "Po rozpoczęciu takbir (można również powiedzieć zamiast Sany).", "Prorok ﷺ wyrecytował to pomiędzy takbirem a recytacją."),
        "dua_hamdan_kathiran" to DuaText("Obfite pochwały po Ruku", "Panie nasz, Tobie należy się chwała – obfita, czysta i błogosławiona chwała.", "Po powstaniu z ruku, razem z „Rabbana lakal-hamd”.", "Ponad trzydziestu aniołów ścigało się, aby jako pierwsi to nagrać."),
    )
}
